  function bindShell(){
    const sidebar=document.getElementById("slSidebar"),overlay=document.getElementById("slOverlay"),menu=document.getElementById("slMenuBtn"),languageButton=document.getElementById("slLanguage"),languageMenu=document.getElementById("slLanguageMenu");
    const closeMenu=()=>{sidebar.classList.remove("open");overlay.classList.remove("show")};menu.addEventListener("click",()=>{sidebar.classList.toggle("open");overlay.classList.toggle("show")});overlay.addEventListener("click",closeMenu);
    document.getElementById("slApp").addEventListener("click",event=>{const link=event.target.closest("a[href]");if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const file=new URL(link.href,location.href).pathname.split("/").pop(),next=link.dataset.routePage||pageByFile[file];if(!next)return;event.preventDefault();closeMenu();navigate(next,true)});
    languageButton.addEventListener("click",event=>{event.stopPropagation();const show=!languageMenu.classList.contains("show");languageMenu.classList.toggle("show",show);languageButton.setAttribute("aria-expanded",String(show))});languageMenu.addEventListener("click",event=>event.stopPropagation());languageMenu.querySelectorAll("[data-language]").forEach(button=>button.addEventListener("click",()=>setLanguage(button.dataset.language)));
    document.getElementById("slSound").addEventListener("click",event=>{soundEnabled=!soundEnabled;localStorage.setItem("varex_dining_sound",soundEnabled?"on":"off");event.currentTarget.classList.toggle("active",soundEnabled);event.currentTarget.setAttribute("aria-pressed",String(soundEnabled));if(soundEnabled)clickTone()});
    document.getElementById("slHaptic").addEventListener("click",event=>{hapticEnabled=!hapticEnabled;localStorage.setItem("varex_dining_haptic",hapticEnabled?"on":"off");event.currentTarget.classList.toggle("active",hapticEnabled);event.currentTarget.setAttribute("aria-pressed",String(hapticEnabled));if(hapticEnabled&&navigator.vibrate)navigator.vibrate(18)});
    document.getElementById("slSwitchUser").addEventListener("click",()=>{window.VAREX?.clearStaffSession?.();location.href="./index.html"});
    document.getElementById("slLogout").addEventListener("click",()=>openConfirm(t("تسجيل الخروج من VAREX؟","Sign out of VAREX?"),t("سيتم إنهاء الجلسة المحلية والعودة إلى الصفحة الرئيسية.","The local session will close and return to the home page."),()=>{window.VAREX?.logout?.(true);location.href="./index.html"}));updateClock();clearInterval(clockTimer);clockTimer=setInterval(updateClock,30000);
  }
  function updateRouteChrome(){const meta=pageMeta[page]||pageMeta.dashboard;document.body.dataset.diningPage=page;document.title="VAREX DINING | "+t(meta[3],meta[4]);document.querySelectorAll(".sl-nav a[data-route-page]").forEach(link=>link.classList.toggle("active",link.dataset.routePage===page));const icon=document.querySelector(".sl-page-icon"),title=document.querySelector(".sl-page-title h2");if(icon)icon.innerHTML=svg(page);if(title)title.textContent=t(meta[3],meta[4])}
  function navigate(next,push=true){if(!pageMeta[next])return;page=next;filters={search:"",status:"all",category:"all"};updateRouteChrome();renderPage();window.scrollTo({top:0,behavior:"auto"});if(push)history.pushState({diningPage:page},"",href(pageMeta[page][1]))}
