  function renderOrders(){const items=data.orders.filter(matches).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));return hero(t("إدارة دورة الطلب","ORDER WORKFLOW"),t("إدارة الطلبات","Order Management"),t("تابع طلبات الصالة والسفري والتوصيل من التسجيل وحتى الجاهزية والإغلاق.","Track dine-in, takeaway and delivery orders from entry to readiness and closure."))+`<div class="sl-kpi-grid">${kpi("orders",t("كل الطلبات","All Orders"),data.orders.length,t("الطلبات المسجلة","Recorded orders"))}${kpi("clock",t("قيد التحضير","Preparing"),data.orders.filter(x=>x.status==="preparing").length,t("داخل المطبخ","In kitchen"))}${kpi("kitchen",t("جاهزة للتسليم","Ready"),data.orders.filter(x=>x.status==="ready").length,t("بانتظار التقديم","Awaiting service"))}${kpi("pos",t("قيمة الطلبات","Order Value"),money(data.orders.reduce((s,x)=>s+x.total,0)),t("إجمالي السجل","Total register"))}</div>${toolbar(["new","preparing","ready","completed","cancelled"])}<div class="sl-order-grid">${items.map(order=>`<article class="sl-order-card"><header><div><h3>#${esc(order.number)}</h3><p>${esc(order.date)} · ${esc(order.time)}</p></div>${badge(order.status)}</header><p>${esc(order.items.map(i=>i.qty+"× "+i.name).join("، "))}</p><div class="sl-order-meta"><span>${orderType(order.type)}</span>${order.tableId?`<span>${esc(find("tables",order.tableId)?.name||order.tableId)}</span>`:""}<span>${money(order.total)}</span></div>${["new","preparing","ready"].includes(order.status)?`<button class="sl-btn soft" style="margin-top:12px" type="button" data-order-next="${esc(order.id)}">${nextOrderLabel(order.status)}</button>`:""}</article>`).join("")||empty()}</div>`}
  function renderTables(){return hero(t("إدارة الصالة","FLOOR MANAGEMENT"),t("الطاولات والحجوزات","Tables & Reservations"),t("راقب حالة الطاولات وسعتها وموقعها والطلب المرتبط بها.","Monitor table status, capacity, area and linked order."),"tables",t("إضافة طاولة","Add Table"))+`<div class="sl-kpi-grid">${kpi("tables",t("إجمالي الطاولات","Total Tables"),data.tables.length,t("كل مناطق الجلوس","All seating areas"))}${kpi("orders",t("مشغولة","Occupied"),data.tables.filter(x=>x.status==="occupied").length,t("عليها طلبات نشطة","With active orders"))}${kpi("calendar",t("محجوزة","Reserved"),data.tables.filter(x=>x.status==="reserved").length,t("حجوزات قادمة","Upcoming reservations"))}${kpi("tables",t("متاحة","Available"),data.tables.filter(x=>x.status==="available").length,t("جاهزة لاستقبال العملاء","Ready for guests"))}</div><div class="sl-table-grid">${data.tables.filter(matches).map(x=>`<article class="sl-table-card"><div class="sl-card-top"><span class="sl-service-icon">${svg("tables")}</span>${badge(x.status)}</div><h3>${esc(x.name)}</h3><p>${esc(x.area)} · ${esc(x.seats)} ${t("مقاعد","seats")}</p><div class="sl-service-price"><strong>${x.orderId?"#"+esc(find("orders",x.orderId)?.number||x.orderId):t("لا يوجد طلب","No order")}</strong>${actions("tables",x.id)}</div></article>`).join("")}</div>`}
