  function fieldHtml(field,value){const[name,ar,en,type,required,options]=field,label=t(ar,en),req=required?"required":"";if(type==="status")return`<div class="sl-form-group"><label>${label}${required?" *":""}</label><select name="${name}" ${req}><option value="">${t("اختيار","Select")}</option>${(options||[]).map(x=>`<option value="${esc(x)}" ${String(value)===String(x)?"selected":""}>${t(...(statusText[x]||[x,x]))}</option>`).join("")}</select></div>`;return`<div class="sl-form-group"><label>${label}${required?" *":""}</label><input name="${name}" type="${type}" value="${esc(value??"")}" ${type==="number"?'min="0" step="any"':""} ${req}></div>`}
  function openForm(type,id){const config=formConfigs[type];if(!config)return;const record=id?find(type,id):{};const modal=document.getElementById("slModal");modal.innerHTML=`<section class="sl-modal"><header class="sl-modal-head"><h3>${t(...config.title)}</h3><button class="sl-modal-close" type="button" data-close-modal>×</button></header><div class="sl-modal-body"><form id="slRecordForm" class="sl-form">${config.fields.map(field=>fieldHtml(field,record?.[field[0]])).join("")}<div class="sl-form-group full"><div class="sl-modal-actions"><button class="sl-btn ghost" type="button" data-close-modal>${t("إلغاء","Cancel")}</button><button class="sl-btn" type="submit">${t("حفظ البيانات","Save Record")}</button></div></div></form></div></section>`;modal.classList.add("show");modal.querySelectorAll("[data-close-modal]").forEach(button=>button.addEventListener("click",closeModal));modal.querySelector("#slRecordForm").addEventListener("submit",event=>saveRecord(event,type,id))}
  function saveRecord(event,type,id){event.preventDefault();const config=formConfigs[type],form=new FormData(event.currentTarget),record=id?find(type,id):{id:uid(prefixes[type]||"FD")};for(const field of config.fields){const value=form.get(field[0]);record[field[0]]=field[3]==="number"?Number(value||0):String(value||"").trim()}if(type==="ingredients")record.status=record.quantity===0?"out":record.quantity<=record.minStock?"low":"available";if(type==="tables"&&!record.orderId)record.orderId="";if(!id)data[type].unshift(record);data.activities.unshift({icon:"✓",title:{ar:"تحديث في نظام "+(diningType==="restaurant"?"المطاعم":"المقاهي"),en:"Dining System Update"},detail:{ar:"تم حفظ سجل جديد",en:"A new record was saved"},time:{ar:"الآن",en:"Now"}});data.activities=data.activities.slice(0,8);save();closeModal();renderPage();toast(t("تم حفظ البيانات بنجاح","Record saved successfully"))}
  function confirmDelete(type,id){if(!find(type,id))return;openConfirm(t("تأكيد حذف السجل","Confirm Record Deletion"),t("سيتم حذف هذا السجل من النظام.","This record will be removed from the system."),()=>{data[type]=data[type].filter(x=>String(x.id)!==String(id));save();renderPage();toast(t("تم حذف السجل","Record deleted"))})}
  function openConfirm(title,message,onAccept){pendingConfirm=onAccept;const modal=document.getElementById("slConfirm");modal.innerHTML=`<section class="sl-modal sl-confirm"><div class="sl-modal-body"><span class="sl-confirm-icon">!</span><h3>${title}</h3><p>${message}</p><div class="sl-modal-actions"><button class="sl-btn ghost" type="button" data-cancel-confirm>${t("إلغاء","Cancel")}</button><button class="sl-btn danger" type="button" data-accept-confirm>${t("تأكيد","Confirm")}</button></div></div></section>`;modal.classList.add("show");modal.querySelector("[data-cancel-confirm]").addEventListener("click",closeConfirm);modal.querySelector("[data-accept-confirm]").addEventListener("click",()=>{const action=pendingConfirm;closeConfirm();action?.()})}
  function closeModal(){const modal=document.getElementById("slModal");modal.classList.remove("show");modal.innerHTML=""}function closeConfirm(){const modal=document.getElementById("slConfirm");modal.classList.remove("show");modal.innerHTML="";pendingConfirm=null}function toast(message){const el=document.getElementById("slToast");el.querySelector("span").textContent=message;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2400)}
  function addToCart(id){const item=find("menuItems",id);if(!item)return;const line=data.cart.find(x=>x.id===id);if(line)line.qty+=1;else data.cart.push({id:item.id,name:item.name,price:item.price,qty:1});save();feedback();renderPage()}function changeCart(id,delta){const line=data.cart.find(x=>x.id===id);if(!line)return;line.qty+=delta;if(line.qty<=0)data.cart=data.cart.filter(x=>x.id!==id);save();renderPage()}function removeFromCart(id){data.cart=data.cart.filter(x=>x.id!==id);save();renderPage()}
  function createOrder(completed){if(!data.cart.length)return;const subtotal=data.cart.reduce((s,x)=>s+x.price*x.qty,0),tax=subtotal*Number(data.settings.vat||0)/100,total=subtotal+tax,type=document.getElementById("slOrderType")?.value||"takeaway",tableId=document.getElementById("slOrderTable")?.value||"",payment=document.getElementById("slPayment")?.value||"cash",number=String(1000+data.orders.length+1),order={id:uid("OR"),number,date:today(),time:nowTime(),type,tableId,items:data.cart.map(x=>({...x})),status:completed?"completed":"new",payment,total};data.orders.unshift(order);if(tableId){const table=find("tables",tableId);if(table){table.status=completed?"available":"occupied";table.orderId=completed?"":order.id}}data.cart=[];data.activities.unshift({icon:completed?"💳":"👨‍🍳",title:{ar:completed?"بيع مكتمل":"طلب جديد",en:completed?"Sale Completed":"New Order"},detail:{ar:"تم تسجيل الطلب رقم "+number,en:"Order "+number+" was recorded"},time:{ar:"الآن",en:"Now"}});save();feedback();renderPage();toast(completed?t("تم البيع والفاتورة جاهزة للطباعة","Sale completed and invoice is ready to print"):t("تم إرسال الطلب إلى المطبخ","Order sent to the kitchen"));if(completed)setTimeout(()=>window.print(),350)}
  function nextOrderLabel(status){return status==="new"?t("بدء التحضير","Start Preparing"):status==="preparing"?t("تحديد كجاهز","Mark Ready"):t("إكمال وتسليم","Complete & Serve")}
  function advanceOrder(id){const order=find("orders",id);if(!order)return;order.status=order.status==="new"?"preparing":order.status==="preparing"?"ready":"completed";if(order.status==="completed"&&order.tableId){const table=find("tables",order.tableId);if(table){table.status="available";table.orderId=""}}save();feedback();renderPage();toast(t("تم تحديث حالة الطلب","Order status updated"))}
  function saveSettings(event){event.preventDefault();const form=new FormData(event.currentTarget);["businessName","phone","email","address","workingStart","workingEnd"].forEach(key=>data.settings[key]=String(form.get(key)||"").trim());["vat","serviceCharge"].forEach(key=>data.settings[key]=Number(form.get(key)||0));save();toast(t("تم حفظ إعدادات النظام","System settings saved"))}
